type View = "dashboard" | "ingestion" | "transactions" | "graph" | "anomaly" | "clusters" | "alerts" | "geo" | "reports" | "settings";

const riskClass: Record<RiskLevel, string> = {
  Low: "bg-safe/12 text-safe ring-safe/25",
  Medium: "bg-amber/12 text-amber ring-amber/25",
  High: "bg-risk/12 text-risk ring-risk/25",
  Critical: "bg-crit/12 text-crit ring-crit/25",
};

const navItems: { id: View; label: string; icon: typeof Grid3X3; count?: string }[] = [
  { id: "dashboard", label: "Dashboard", icon: Grid3X3 },
  { id: "ingestion", label: "Data Ingestion", icon: HardDriveUpload },
  { id: "transactions", label: "Transaction Explorer", icon: Table2 },
  { id: "graph", label: "Entity Graph", icon: Network },
  { id: "anomaly", label: "AI Anomaly Detection", icon: Bot },
  { id: "clusters", label: "Entity Clusters", icon: CircleDot },
  { id: "alerts", label: "Investigation Alerts", icon: Bell, count: "37" },
  { id: "geo", label: "Geo Network", icon: Globe2 },
  { id: "reports", label: "Reports", icon: FileBarChart },
  { id: "settings", label: "Settings", icon: Settings2 },
];

const shortId = (value: string, length = 12) => value.length > length ? `${value.slice(0, 6)}…${value.slice(-4)}` : value;
const fmtDate = (value: string) => new Intl.DateTimeFormat("en-GB", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit", hour12: false }).format(new Date(value));
const fmtBtc = (value: number) => `${value.toFixed(4)} BTC`;

function RiskBadge({ risk }: { risk: RiskLevel }) {
  return <span className={cn("inline-flex rounded-md px-2 py-0.5 text-[10px] font-mono uppercase tracking-wide ring-1", riskClass[risk])}>{risk}</span>;
}

function Panel({ className, children }: { className?: string; children: React.ReactNode }) {
  return <section className={cn("bt-glass rounded-xl ring-1 ring-line/70", className)}>{children}</section>;
}

function SectionHeader({ title, eyebrow, action }: { title: string; eyebrow?: string; action?: React.ReactNode }) {
  return <div className="flex items-end justify-between gap-4">
    <div>
      {eyebrow && <div className="mb-1 font-mono text-[10px] uppercase tracking-[0.18em] text-faint">{eyebrow}</div>}
      <h1 className="text-2xl font-semibold tracking-tight text-ink">{title}</h1>
    </div>
    {action}
  </div>;
}

function EmptyState({ icon: Icon, title, description, action }: { icon: typeof Upload; title: string; description: string; action?: React.ReactNode }) {
  return <div className="grid min-h-[360px] place-items-center rounded-xl border border-dashed border-line bg-panel/20 p-8 text-center">
    <div className="max-w-sm">
      <div className="mx-auto mb-4 grid size-12 place-items-center rounded-xl bg-cyan/10 text-cyan ring-1 ring-cyan/25"><Icon className="size-5" /></div>
      <h2 className="text-lg font-semibold text-ink">{title}</h2>
      <p className="mt-2 text-sm leading-relaxed text-mute">{description}</p>
      {action && <div className="mt-5">{action}</div>}
    </div>
  </div>;
}

function Dashboard({ onEntity, onView }: { onEntity: (entity: Entity) => void; onView: (view: View) => void }) {
  const topEntities = entities.slice(30, 34);
  const donutColors = ["var(--color-safe)", "var(--color-amber)", "var(--color-risk)", "var(--color-crit)"];
  return <div className="space-y-6">
    <SectionHeader title="Investigator Dashboard" eyebrow="Investigator Console" action={<div className="text-right"><div className="font-mono text-[10px] uppercase tracking-wider text-faint">Last synced</div><div className="font-mono text-sm text-ink">08:42:19 UTC</div></div>} />
    <p className="-mt-4 max-w-2xl text-sm text-mute">Prioritized forensic leads from 24,581 correlated transaction and network records.</p>
    <div className="grid grid-cols-12 gap-4">
      <Panel className="col-span-12 p-5 lg:col-span-3 bg-cyan/8 ring-cyan/25">
        <div className="font-mono text-[11px] uppercase tracking-wider text-cyan">Avg Anomaly Score</div>
        <div className="mt-2 flex items-end gap-3"><span className="text-5xl font-semibold leading-none text-ink">0.67</span><span className="mb-1 font-mono text-[11px] text-mute">/ 1.00</span></div>
        <div className="mt-4 h-1.5 overflow-hidden rounded-full bg-void/80"><div className="h-full w-[67%] rounded-full bg-gradient-to-r from-blue via-cyan to-amber" /></div>
        <div className="mt-2 text-xs text-mute">Investigative prioritization index</div>
      </Panel>
      {[{ label: "Total Transactions", value: "24,581", note: "↑ 4.2% vs prior window" }, { label: "Wallet Entities", value: "8,942", note: "1,204 active this period" }, { label: "Network IPs", value: "3,216", note: "across 14 ASNs" }].map((item) => <Panel key={item.label} className="col-span-12 p-4 sm:col-span-4 lg:col-span-2"><div className="font-mono text-[11px] uppercase tracking-wider text-faint">{item.label}</div><div className="mt-2 text-3xl font-semibold leading-none text-ink">{item.value}</div><div className="mt-2 font-mono text-[11px] text-mute">{item.note}</div></Panel>)}
      <Panel className="col-span-12 bg-crit/8 p-4 ring-crit/25 sm:col-span-4 lg:col-span-2"><div className="flex items-center gap-1.5 font-mono text-[11px] uppercase tracking-wider text-crit"><span className="bt-pulse size-1.5 rounded-full bg-crit" />High-Risk Alerts</div><div className="mt-2 text-3xl font-semibold leading-none text-crit">37</div><div className="mt-2 font-mono text-[11px] text-crit/70">184 suspicious entities</div></Panel>
    </div>
    <div className="grid grid-cols-12 gap-4">
      <Panel className="col-span-12 p-5 lg:col-span-8">
        <div className="mb-5 flex items-start justify-between"><div><h2 className="text-sm font-semibold text-ink">Transaction Activity Over Time</h2><p className="mt-0.5 font-mono text-[11px] text-faint">Normal vs. flagged volume · 16-day window</p></div><div className="flex gap-3 font-mono text-[11px] text-mute"><span className="flex items-center gap-1.5"><span className="size-2 rounded-full bg-blue" />Normal</span><span className="flex items-center gap-1.5"><span className="size-2 rounded-full bg-risk" />Suspicious</span></div></div>
        <div className="h-56 w-full"><ResponsiveContainer width="100%" height="100%"><AreaChart data={activity}><defs><linearGradient id="normalFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="var(--color-blue)" stopOpacity={0.32} /><stop offset="100%" stopColor="var(--color-blue)" stopOpacity={0} /></linearGradient><linearGradient id="suspiciousFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="var(--color-risk)" stopOpacity={0.36} /><stop offset="100%" stopColor="var(--color-risk)" stopOpacity={0} /></linearGradient></defs><CartesianGrid stroke="var(--color-line)" strokeDasharray="3 4" opacity={0.5} /><XAxis dataKey="day" tick={{ fill: "var(--color-faint)", fontSize: 10 }} axisLine={false} tickLine={false} /><YAxis tick={{ fill: "var(--color-faint)", fontSize: 10 }} axisLine={false} tickLine={false} width={34} /><Tooltip contentStyle={{ background: "var(--color-panel-strong)", border: "1px solid var(--color-line)", borderRadius: 8, color: "var(--color-ink)" }} /><Area type="monotone" dataKey="normal" stroke="var(--color-blue)" fill="url(#normalFill)" strokeWidth={2} /><Area type="monotone" dataKey="suspicious" stroke="var(--color-risk)" fill="url(#suspiciousFill)" strokeWidth={2} /></AreaChart></ResponsiveContainer></div>
      </Panel>
      <Panel className="col-span-12 p-5 lg:col-span-4"><h2 className="text-sm font-semibold text-ink">Risk Distribution</h2><p className="mt-0.5 font-mono text-[11px] text-faint">184 suspicious entities</p><div className="mt-3 flex items-center gap-4"><div className="h-36 w-36 shrink-0"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={riskDistribution} dataKey="value" nameKey="name" innerRadius={45} outerRadius={64} paddingAngle={3} stroke="none">{riskDistribution.map((entry, index) => <Cell key={entry.name} fill={donutColors[index]} />)}</Pie><Tooltip contentStyle={{ background: "var(--color-panel-strong)", border: "1px solid var(--color-line)", borderRadius: 8 }} /></PieChart></ResponsiveContainer></div><div className="space-y-2 font-mono text-xs">{riskDistribution.map((item, index) => <div key={item.name} className="flex items-center gap-2"><span className="size-2.5 rounded-sm" style={{ background: donutColors[index] }} /><span className="w-16 text-mute">{item.name}</span><span className="text-ink">{item.value}</span></div>)}</div></div></Panel>
    </div>
    <div className="grid grid-cols-12 gap-4">
      <Panel className="col-span-12 overflow-hidden lg:col-span-8"><div className="flex items-center justify-between px-5 pb-3 pt-4"><div><h2 className="text-sm font-semibold text-ink">Top Suspicious Entities</h2><p className="mt-0.5 font-mono text-[11px] text-faint">Highest anomaly scores · click a row to investigate</p></div><Button variant="link" size="sm" className="text-cyan" onClick={() => onView("alerts")}>View all <ChevronRight /></Button></div><div className="overflow-x-auto"><table className="w-full text-left"><thead className="border-y border-line/60 bg-panel/40 font-mono text-[10px] uppercase tracking-wider text-faint"><tr><th className="px-5 py-2">Entity</th><th className="px-3 py-2">Type</th><th className="px-3 py-2">Risk</th><th className="px-3 py-2">Score</th><th className="px-5 py-2">Reason</th></tr></thead><tbody className="font-mono text-xs">{topEntities.map((entity) => <tr key={entity.id} className="cursor-pointer border-b border-line/40 transition-colors hover:bg-cyan/5" onClick={() => onEntity(entity)}><td className="px-5 py-3 text-cyan">{shortId(entity.id)}</td><td className="px-3 py-3 text-mute">{entity.type}</td><td className="px-3 py-3"><RiskBadge risk={riskForScore(entity.anomalyScore)} /></td><td className="px-3 py-3 text-ink">{entity.anomalyScore.toFixed(2)}</td><td className="px-5 py-3 text-mute">{entity.reason}</td></tr>)}</tbody></table></div></Panel>
      <Panel className="col-span-12 p-5 lg:col-span-4"><div className="flex items-start justify-between"><div><h2 className="text-sm font-semibold text-ink">Suspicious Activity Types</h2><p className="mt-0.5 font-mono text-[11px] text-faint">Model reason codes</p></div><Zap className="size-4 text-cyan" /></div><div className="mt-4 h-48"><ResponsiveContainer width="100%" height="100%"><BarChart data={activityTypes} layout="vertical" margin={{ left: 5, right: 8 }}><XAxis type="number" hide /><YAxis type="category" dataKey="name" width={126} tick={{ fill: "var(--color-mute)", fontSize: 10 }} axisLine={false} tickLine={false} /><Bar dataKey="value" fill="var(--color-cyan)" radius={[0, 4, 4, 0]} /></BarChart></ResponsiveContainer></div></Panel>
    </div>
  </div>;
}

function Ingestion({ onRun }: { onRun: () => void }) {
  const [fileName, setFileName] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  return <div className="space-y-6"><SectionHeader title="Data Ingestion" eyebrow="Offline Pipeline" action={<span className="rounded-md bg-amber/10 px-2.5 py-1 font-mono text-[10px] uppercase tracking-wider text-amber ring-1 ring-amber/25">Local processing only</span>} /><Panel className="p-6"><div className="mb-5"><h2 className="text-lg font-semibold text-ink">Import Investigation Dataset</h2><p className="mt-1 text-sm text-mute">Upload synthetic transaction and network metadata for correlation, anomaly detection, and graph construction.</p></div><div className="rounded-xl border border-dashed border-cyan/35 bg-cyan/5 p-10 text-center" onDragOver={(event) => event.preventDefault()} onDrop={(event) => { event.preventDefault(); const file = event.dataTransfer.files[0]; if (file) setFileName(file.name); }}><input ref={inputRef} type="file" accept=".csv,.json,.xml" className="hidden" onChange={(event) => setFileName(event.target.files?.[0]?.name ?? null)} /><div className="mx-auto grid size-12 place-items-center rounded-xl bg-cyan/10 text-cyan ring-1 ring-cyan/25"><Upload className="size-5" /></div><h3 className="mt-4 text-base font-semibold text-ink">{fileName ?? "Drop a dataset here"}</h3><p className="mt-1 font-mono text-xs text-faint">CSV · JSON · XML · max 20 MB</p><Button variant="outline" className="mt-5 border-cyan/30 text-cyan hover:bg-cyan/10" onClick={() => inputRef.current?.click()}><HardDriveUpload />{fileName ? "Replace file" : "Choose file"}</Button><p className="mt-4 text-xs text-safe">Offline processing — files remain on the local system.</p></div></Panel><Panel className="p-5"><div className="flex items-center justify-between"><div><h2 className="text-sm font-semibold text-ink">Dataset Summary</h2><p className="mt-1 font-mono text-[11px] text-faint">Synthetic preview schema</p></div><span className="rounded-md bg-safe/10 px-2 py-1 font-mono text-[10px] text-safe ring-1 ring-safe/20">{fileName ? "READY" : "NO DATASET"}</span></div><div className="mt-4 grid grid-cols-2 gap-3 md:grid-cols-5">{[["File", fileName ?? "—"], ["Records", fileName ? "540" : "—"], ["Wallets", fileName ? "224" : "—"], ["IP addresses", fileName ? "128" : "—"], ["Date range", fileName ? "12–28 Mar 2026" : "—"]].map(([label, value]) => <div key={label} className="rounded-lg bg-panel/55 p-3 ring-1 ring-line/60"><div className="font-mono text-[10px] uppercase tracking-wider text-faint">{label}</div><div className="mt-1 truncate text-xs text-ink">{value}</div></div>)}</div><div className="mt-5 overflow-x-auto"><table className="w-full text-left font-mono text-xs"><thead className="border-y border-line/60 text-[10px] uppercase tracking-wider text-faint"><tr>{["timestamp", "src_ip", "txid", "input_addresses", "output_addresses", "fee", "script_type", "geo_country", "asn"].map((field) => <th key={field} className="px-3 py-2 first:pl-0">{field}</th>)}</tr></thead><tbody>{transactions.slice(0, 3).map((tx) => <tr key={tx.txid} className="border-b border-line/40 text-mute"><td className="px-3 py-2 pl-0">{fmtDate(tx.timestamp)}</td><td className="px-3 py-2">{tx.srcIp}</td><td className="px-3 py-2 text-cyan">{shortId(tx.txid)}</td><td className="px-3 py-2">{shortId(tx.inputAddresses[0])}</td><td className="px-3 py-2">{shortId(tx.outputAddresses[0])}</td><td className="px-3 py-2">{tx.fee}</td><td className="px-3 py-2">{tx.scriptType}</td><td className="px-3 py-2">{tx.country}</td><td className="px-3 py-2">{tx.asn}</td></tr>)}</tbody></table></div><div className="mt-5 flex justify-end"><Button className="bg-cyan text-primary-foreground hover:bg-cyan/90" disabled={!fileName} onClick={onRun}><Play />Run AI Analysis</Button></div></Panel></div>;
}

function Transactions({ onSelect }: { onSelect: (tx: Transaction) => void }) {
  const [query, setQuery] = useState("");
  const [risk, setRisk] = useState("All risk");
  const [country, setCountry] = useState("All countries");
  const filtered = useMemo(() => transactions.filter((tx) => {
    const matchesQuery = !query || [tx.txid, ...tx.inputAddresses, ...tx.outputAddresses, tx.srcIp, tx.dstIp, tx.asn].some((item) => item.toLowerCase().includes(query.toLowerCase()));
    const matchesRisk = risk === "All risk" || tx.risk === risk;
    const matchesCountry = country === "All countries" || tx.country === country;
    return matchesQuery && matchesRisk && matchesCountry;
  }).slice(0, 80), [query, risk, country]);
  return <div className="space-y-5"><SectionHeader title="Transaction Explorer" eyebrow="Correlated Metadata" action={<div className="flex items-center gap-2"><span className="rounded-md bg-panel px-2.5 py-1 font-mono text-[10px] text-mute ring-1 ring-line">{filtered.length} visible</span><Button variant="outline" size="sm"><Download />Export CSV</Button></div>} /><Panel className="p-4"><div className="grid gap-3 md:grid-cols-[1fr_150px_170px_auto]"><div className="relative"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-faint" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search TXID, wallet, IP, ASN…" className="h-9 w-full rounded-lg border border-line bg-panel/60 pl-9 pr-3 text-sm text-ink outline-none placeholder:text-faint focus:border-cyan/50" /></div><select value={risk} onChange={(event) => setRisk(event.target.value)} className="h-9 rounded-lg border border-line bg-panel/60 px-3 text-xs text-mute outline-none"><option>All risk</option><option>Low</option><option>Medium</option><option>High</option><option>Critical</option></select><select value={country} onChange={(event) => setCountry(event.target.value)} className="h-9 rounded-lg border border-line bg-panel/60 px-3 text-xs text-mute outline-none"><option>All countries</option>{geo.map((item) => <option key={item.country}>{item.country}</option>)}</select><Button variant="outline" size="sm"><Filter />Filters</Button></div></Panel><Panel className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[1050px] text-left"><thead className="border-b border-line bg-panel/50 font-mono text-[10px] uppercase tracking-wider text-faint"><tr>{["TXID", "Timestamp", "Input Wallets", "Output Wallets", "Input Amount", "Output Amount", "Fee", "Source IP", "Destination IP", "Country", "ASN", "Risk", "Status"].map((head) => <th key={head} className="px-3 py-3 first:pl-5">{head}</th>)}</tr></thead><tbody className="font-mono text-xs">{filtered.map((tx) => <tr key={tx.txid} onClick={() => onSelect(tx)} className="cursor-pointer border-b border-line/40 transition-colors hover:bg-cyan/5"><td className="px-3 py-3 pl-5 text-cyan">{shortId(tx.txid)}</td><td className="whitespace-nowrap px-3 py-3 text-mute">{fmtDate(tx.timestamp)}</td><td className="px-3 py-3 text-mute">{tx.inputAddresses.length}</td><td className="px-3 py-3 text-mute">{tx.outputAddresses.length}</td><td className="px-3 py-3 text-ink">{fmtBtc(tx.inputAmount)}</td><td className="px-3 py-3 text-ink">{fmtBtc(tx.outputAmount)}</td><td className="px-3 py-3 text-mute">{tx.fee}</td><td className="px-3 py-3 text-mute">{tx.srcIp}</td><td className="px-3 py-3 text-mute">{tx.dstIp}</td><td className="px-3 py-3 text-mute">{tx.country}</td><td className="px-3 py-3 text-mute">{tx.asn}</td><td className="px-3 py-3"><RiskBadge risk={tx.risk} /></td><td className="px-3 py-3"><span className={cn("rounded-md px-2 py-0.5 text-[10px]", tx.status === "Flagged" ? "bg-risk/10 text-risk" : "bg-safe/10 text-safe")}>{tx.status}</span></td></tr>)}</tbody></table></div></Panel></div>;
}

function TransactionDrawer({ tx, onClose }: { tx: Transaction; onClose: () => void }) {
  const contributions = [["Rapid fund movement", 0.24, "risk"], ["Wallet connectivity", 0.21, "risk"], ["Amount anomaly", 0.18, "amber"], ["IP correlation", 0.13, "amber"], ["Geographic deviation", 0.09, "blue"]] as const;
  return <Drawer title="Transaction Investigation" onClose={onClose}><div className="space-y-5"><div className="flex items-center justify-between"><div><div className="font-mono text-xs text-cyan">{tx.txid}</div><div className="mt-1 text-xs text-mute">{fmtDate(tx.timestamp)} UTC</div></div><div className="text-right"><div className="font-mono text-2xl font-semibold text-crit">{tx.riskScore.toFixed(2)}</div><RiskBadge risk={tx.risk} /></div></div><Panel className="p-4"><div className="mb-4 text-[10px] font-mono uppercase tracking-wider text-faint">Transaction Flow</div><div className="grid grid-cols-[1fr_auto_1fr] items-center gap-2 text-center"><div><div className="mx-auto mb-2 grid size-10 place-items-center rounded-full bg-blue/15 text-blue ring-1 ring-blue/30"><CircleDot /></div><div className="font-mono text-[10px] text-mute">SOURCE WALLET</div><div className="mt-1 break-all font-mono text-[10px] text-ink">{shortId(tx.inputAddresses[0], 16)}</div></div><ChevronRight className="text-cyan" /><div><div className="mx-auto mb-2 grid size-10 place-items-center rounded-md bg-risk/15 text-risk ring-1 ring-risk/30"><Zap /></div><div className="font-mono text-[10px] text-mute">DESTINATION</div><div className="mt-1 break-all font-mono text-[10px] text-ink">{shortId(tx.outputAddresses[0], 16)}</div></div></div></Panel><div className="grid grid-cols-2 gap-2">{[["Input amount", fmtBtc(tx.inputAmount)], ["Output amount", fmtBtc(tx.outputAmount)], ["Fee", `${tx.fee} BTC`], ["Script type", tx.scriptType], ["Source IP", tx.srcIp], ["Destination IP", tx.dstIp], ["Ports", `${tx.srcPort} → ${tx.dstPort}`], ["Country / ASN", `${tx.country} · ${tx.asn}`]].map(([label, value]) => <div key={label} className="rounded-lg bg-panel/55 p-3 ring-1 ring-line/60"><div className="font-mono text-[10px] uppercase tracking-wider text-faint">{label}</div><div className="mt-1 break-all font-mono text-xs text-ink">{value}</div></div>)}</div><Panel className="p-4"><div className="mb-3 flex items-center gap-2"><Sparkles className="size-4 text-cyan" /><div><div className="text-sm font-semibold text-ink">Why was this transaction flagged?</div><div className="font-mono text-[10px] text-faint">Explainable feature contributions</div></div></div><div className="space-y-3">{contributions.map(([label, value, color]) => <div key={label}><div className="mb-1 flex justify-between font-mono text-[11px]"><span className="text-mute">{label}</span><span className="text-ink">+{value.toFixed(2)}</span></div><div className="h-1.5 rounded-full bg-void"><div className={cn("h-full rounded-full", color === "risk" ? "bg-risk" : color === "amber" ? "bg-amber" : "bg-blue")} style={{ width: `${Math.round(value / 0.24 * 100)}%` }} /></div></div>)}</div><p className="mt-4 text-xs leading-relaxed text-mute">High anomaly score because the transaction shows unusually rapid fund movement, connects to multiple wallet entities, and deviates from the normal amount distribution. This is an AI-prioritized investigation lead, not proof of criminal activity.</p></Panel></div></Drawer>;
}

function Drawer({ title, onClose, children }: { title: string; onClose: () => void; children: React.ReactNode }) {
  return <div className="fixed inset-0 z-50"><button aria-label="Close drawer" className="absolute inset-0 bg-void/70 backdrop-blur-sm" onClick={onClose} /><aside className="absolute right-0 top-0 h-full w-full max-w-xl overflow-y-auto border-l border-line bg-canvas p-6 shadow-2xl shadow-void/60"><div className="mb-6 flex items-center justify-between"><div><div className="font-mono text-[10px] uppercase tracking-[0.18em] text-cyan">Investigation View</div><h2 className="mt-1 text-xl font-semibold text-ink">{title}</h2></div><Button variant="ghost" size="icon" aria-label="Close" onClick={onClose}><X /></Button></div>{children}</aside></div>;
}

function Graph({ onEntity }: { onEntity: (entity: Entity) => void }) {
  const [filter, setFilter] = useState("All entities");
  const graphNodes = [{ id: "IP_23", label: "IP_23", type: "IP", x: 18, y: 28, risk: "High" as RiskLevel }, { id: "TX123", label: "TX-123", type: "Transaction", x: 48, y: 30, risk: "Critical" as RiskLevel }, { id: wallet(32), label: "Wallet A", type: "Wallet", x: 30, y: 58, risk: "Critical" as RiskLevel }, { id: wallet(77), label: "Wallet B", type: "Wallet", x: 70, y: 58, risk: "High" as RiskLevel }, { id: "AS4755", label: "AS4755", type: "ASN", x: 17, y: 74, risk: "Medium" as RiskLevel }, { id: "TX456", label: "TX-456", type: "Transaction", x: 48, y: 75, risk: "High" as RiskLevel }, { id: wallet(19), label: "Wallet C", type: "Wallet", x: 74, y: 86, risk: "Medium" as RiskLevel }];
  const visible = filter === "All entities" ? graphNodes : graphNodes.filter((node) => node.type === filter);
  const edges = [[18, 28, 48, 30], [48, 30, 30, 58], [48, 30, 70, 58], [18, 28, 17, 74], [30, 58, 48, 75], [48, 75, 74, 86], [70, 58, 74, 86]];
  return <div className="space-y-5"><SectionHeader title="Entity Graph" eyebrow="Link Analysis Workspace" action={<div className="flex gap-2"><select value={filter} onChange={(event) => setFilter(event.target.value)} className="h-9 rounded-lg border border-line bg-panel/60 px-3 text-xs text-mute"><option>All entities</option><option>Wallet</option><option>Transaction</option><option>IP</option><option>ASN</option></select><Button variant="outline" size="sm"><SlidersHorizontal />Graph filters</Button></div>} /><Panel className="relative min-h-[620px] overflow-hidden bg-void/35"><div className="absolute inset-0 opacity-40" style={{ backgroundImage: "linear-gradient(var(--color-line) 1px, transparent 1px), linear-gradient(90deg, var(--color-line) 1px, transparent 1px)", backgroundSize: "34px 34px" }} /><div className="absolute left-5 top-4 z-10 rounded-lg bg-panel/80 px-3 py-2 ring-1 ring-line/70"><div className="font-mono text-[10px] uppercase tracking-wider text-faint">Relationship canvas</div><div className="mt-1 text-xs text-mute">Click a node to inspect connected evidence</div></div><svg className="absolute inset-0 h-full w-full" viewBox="0 0 100 100" preserveAspectRatio="none">{edges.map(([x1, y1, x2, y2], index) => <line key={index} x1={`${x1}%`} y1={`${y1}%`} x2={`${x2}%`} y2={`${y2}%`} stroke="var(--color-cyan)" strokeOpacity="0.32" strokeWidth="0.3" strokeDasharray="1 1" />)}</svg>{visible.map((node) => <button key={node.id} onClick={() => onEntity(findEntity(node.id))} className="absolute z-10 -translate-x-1/2 -translate-y-1/2 text-center" style={{ left: `${node.x}%`, top: `${node.y}%` }}><span className={cn("mx-auto grid size-14 place-items-center shadow-lg transition-transform hover:scale-110", node.type === "Wallet" ? "rounded-full bg-blue/20 text-blue ring-2 ring-blue/50" : node.type === "Transaction" ? "rounded-md bg-risk/20 text-risk ring-2 ring-risk/50" : node.type === "IP" ? "rotate-45 rounded-md bg-amber/20 text-amber ring-2 ring-amber/50" : "rounded-full bg-safe/20 text-safe ring-2 ring-safe/50")}>{node.type === "IP" ? <Network className="-rotate-45 size-5" /> : node.type === "Transaction" ? <Zap className="size-5" /> : node.type === "ASN" ? <Globe2 className="size-5" /> : <CircleDot className="size-5" />}</span><span className="mt-2 block whitespace-nowrap rounded bg-panel/85 px-2 py-1 font-mono text-[10px] text-ink ring-1 ring-line/70">{node.label}</span><span className={cn("mt-1 inline-block rounded px-1.5 py-0.5 font-mono text-[9px]", riskClass[node.risk])}>{node.risk}</span></button>)}</Panel><div className="grid grid-cols-2 gap-3 md:grid-cols-4">{[["Wallet", "blue"], ["Transaction", "risk"], ["IP", "amber"], ["ASN", "safe"]].map(([label, color]) => <div key={label} className="flex items-center gap-2 rounded-lg bg-panel/50 p-3 font-mono text-xs text-mute ring-1 ring-line/60"><span className={cn("size-3", label === "Transaction" ? "rounded-sm" : "rounded-full", color === "blue" ? "bg-blue" : color === "risk" ? "bg-risk" : color === "amber" ? "bg-amber" : "bg-safe")} />{label}</div>)}</div></div>;
}

function Anomaly() {
  const features = ["Transaction amount", "Fee ratio", "Input/output count", "Transaction frequency", "Time between transactions", "Wallet degree", "IP degree", "Connected wallets", "Connected IPs", "Geographic diversity", "ASN diversity", "Incoming/outgoing volume", "Burst activity", "Repeated IP-wallet relationships"];
  return <div className="space-y-6"><SectionHeader title="AI-Powered Anomaly Detection" eyebrow="Model Operations" action={<span className="rounded-md bg-cyan/10 px-2.5 py-1 font-mono text-[10px] uppercase tracking-wider text-cyan ring-1 ring-cyan/25">Isolation Forest · Unsupervised</span>} /><div className="grid grid-cols-12 gap-4"><Panel className="col-span-12 p-6 lg:col-span-7"><div className="flex items-start gap-3"><div className="grid size-10 place-items-center rounded-lg bg-cyan/10 text-cyan ring-1 ring-cyan/25"><Bot /></div><div><h2 className="text-lg font-semibold text-ink">Model purpose</h2><p className="mt-2 max-w-2xl text-sm leading-relaxed text-mute">Machine learning identifies transaction and entity behavior that deviates from learned normal patterns. This prototype combines transaction, network, temporal, and graph-derived features to prioritize investigative leads.</p></div></div><div className="mt-6 rounded-lg border border-amber/25 bg-amber/8 p-4 text-sm leading-relaxed text-amber">Investigative prioritization score, not proof of criminal activity. Synthetic data is used to demonstrate the pipeline.</div><div className="mt-6"><div className="mb-3 flex items-center justify-between"><h3 className="text-sm font-semibold text-ink">Model output</h3><span className="font-mono text-xl text-cyan">0.67</span></div><div className="h-3 rounded-full bg-void"><div className="h-full w-[67%] rounded-full bg-gradient-to-r from-safe via-amber to-crit" /></div><div className="mt-2 flex justify-between font-mono text-[10px] text-faint"><span>0.00 Low</span><span>0.40 Medium</span><span>0.70 High</span><span>0.90 Critical</span><span>1.00</span></div></div></Panel><Panel className="col-span-12 p-6 lg:col-span-5"><div className="flex items-center justify-between"><div><h2 className="text-sm font-semibold text-ink">Feature Engineering</h2><p className="mt-1 font-mono text-[11px] text-faint">Signals passed to the model</p></div><Sparkles className="size-4 text-cyan" /></div><div className="mt-4 grid grid-cols-2 gap-2">{features.map((feature, index) => <div key={feature} className="flex items-center gap-2 rounded-md bg-panel/55 px-3 py-2 font-mono text-[10px] text-mute ring-1 ring-line/50"><span className="text-cyan">{String(index + 1).padStart(2, "0")}</span>{feature}</div>)}</div></Panel></div><Panel className="p-5"><div className="mb-4 flex items-center justify-between"><div><h2 className="text-sm font-semibold text-ink">Anomaly score distribution</h2><p className="mt-1 font-mono text-[11px] text-faint">Synthetic entity population · 0.00 → 1.00</p></div><span className="font-mono text-xs text-mute">DBSCAN ready after scoring</span></div><div className="h-64"><ResponsiveContainer width="100%" height="100%"><LineChart data={entities.slice(0, 48).map((entity, index) => ({ index: index + 1, score: entity.anomalyScore }))}><CartesianGrid stroke="var(--color-line)" strokeDasharray="3 4" opacity={0.5} /><XAxis dataKey="index" tick={{ fill: "var(--color-faint)", fontSize: 10 }} /><YAxis domain={[0, 1]} tick={{ fill: "var(--color-faint)", fontSize: 10 }} /><Line type="monotone" dataKey="score" stroke="var(--color-cyan)" strokeWidth={2} dot={false} /></LineChart></ResponsiveContainer></div></Panel></div>;
}

function Clusters({ onGraph }: { onGraph: () => void }) {
  return <div className="space-y-6"><SectionHeader title="Suspicious Entity Clusters" eyebrow="DBSCAN Candidate Groups" action={<Button className="bg-cyan text-primary-foreground hover:bg-cyan/90" onClick={onGraph}><Network />Open cluster graph</Button>} /><p className="max-w-2xl text-sm text-mute">Related wallets and network observations grouped by transaction behavior, connectivity, frequency, amount patterns, and IP relationships.</p><div className="grid gap-4 md:grid-cols-2">{clusters.map((cluster) => <Panel key={cluster.id} className="p-5 transition-colors hover:ring-cyan/40"><div className="flex items-start justify-between"><div><div className="font-mono text-[10px] uppercase tracking-wider text-cyan">{cluster.id}</div><h2 className="mt-1 text-lg font-semibold text-ink">{cluster.signature}</h2></div><RiskBadge risk={cluster.risk} /></div><div className="mt-5 grid grid-cols-3 gap-3">{[["Wallets", cluster.wallets], ["IPs", cluster.ips], ["Transactions", cluster.transactions]].map(([label, value]) => <div key={label} className="rounded-lg bg-panel/55 p-3 ring-1 ring-line/60"><div className="font-mono text-[10px] uppercase tracking-wider text-faint">{label}</div><div className="mt-1 text-2xl font-semibold text-ink">{value}</div></div>)}</div><div className="mt-4 flex items-center justify-between"><div className="font-mono text-xs text-mute">{cluster.countries.join(" · ")}</div><div className="font-mono text-sm text-cyan">score {cluster.score.toFixed(2)}</div></div><div className="mt-3 h-1.5 rounded-full bg-void"><div className={cn("h-full rounded-full", cluster.risk === "Critical" ? "bg-crit" : cluster.risk === "High" ? "bg-risk" : cluster.risk === "Medium" ? "bg-amber" : "bg-safe")} style={{ width: `${cluster.score * 100}%` }} /></div></Panel>)}</div></div>;
}

function Alerts({ onAlert }: { onAlert: (alert: Alert) => void }) {
  const [status, setStatus] = useState("All statuses");
  const [sort, setSort] = useState("Risk");
  const filtered = useMemo(() => [...alerts].filter((alert) => status === "All statuses" || alert.status === status).sort((a, b) => sort === "Confidence" ? b.confidence - a.confidence : b.anomalyScore - a.anomalyScore), [status, sort]);
  return <div className="space-y-5"><SectionHeader title="Prioritized Investigation Leads" eyebrow="Alert Management" action={<div className="flex gap-2"><select value={sort} onChange={(event) => setSort(event.target.value)} className="h-9 rounded-lg border border-line bg-panel/60 px-3 text-xs text-mute"><option>Risk</option><option>Confidence</option></select><select value={status} onChange={(event) => setStatus(event.target.value)} className="h-9 rounded-lg border border-line bg-panel/60 px-3 text-xs text-mute"><option>All statuses</option><option>New</option><option>Investigating</option><option>Reviewed</option><option>Dismissed</option></select></div>} /><Panel className="overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left"><thead className="border-b border-line bg-panel/50 font-mono text-[10px] uppercase tracking-wider text-faint"><tr>{["Priority", "Entity", "Type", "Risk", "Confidence", "Detection Reason", "Status", "Timestamp"].map((head) => <th key={head} className="px-4 py-3 first:pl-5">{head}</th>)}</tr></thead><tbody className="font-mono text-xs">{filtered.map((alert) => <tr key={alert.id} className="cursor-pointer border-b border-line/40 transition-colors hover:bg-cyan/5" onClick={() => onAlert(alert)}><td className="px-4 py-3 pl-5"><RiskBadge risk={alert.risk} /></td><td className="px-4 py-3 text-cyan">{shortId(alert.entityId)}</td><td className="px-4 py-3 text-mute">{alert.entityType}</td><td className="px-4 py-3 text-ink">{alert.anomalyScore.toFixed(2)}</td><td className="px-4 py-3 text-ink">{alert.confidence.toFixed(2)}</td><td className="max-w-xs px-4 py-3 text-mute">{alert.reasons.slice(0, 2).join(" + ")}</td><td className="px-4 py-3"><span className="rounded-md bg-panel px-2 py-1 text-[10px] text-mute ring-1 ring-line">{alert.status}</span></td><td className="px-4 py-3 text-mute">{fmtDate(alert.timestamp)}</td></tr>)}</tbody></table></div></Panel></div>;
}

function AlertDrawer({ alert, onClose, onGraph }: { alert: Alert; onClose: () => void; onGraph: () => void }) {
  return <Drawer title="Alert Evidence" onClose={onClose}><div className="space-y-5"><div className="rounded-xl border border-crit/25 bg-crit/8 p-4"><div className="flex items-start justify-between"><div><div className="font-mono text-[10px] uppercase tracking-wider text-crit">{alert.id}</div><h3 className="mt-1 text-lg font-semibold text-ink">Suspicious {alert.entityType} Entity</h3><div className="mt-1 font-mono text-xs text-cyan">{alert.entityId}</div></div><RiskBadge risk={alert.risk} /></div><div className="mt-4 grid grid-cols-2 gap-3"><div><div className="font-mono text-[10px] uppercase tracking-wider text-faint">Confidence</div><div className="mt-1 text-2xl font-semibold text-ink">{Math.round(alert.confidence * 100)}%</div></div><div><div className="font-mono text-[10px] uppercase tracking-wider text-faint">Anomaly score</div><div className="mt-1 text-2xl font-semibold text-crit">{Math.round(alert.anomalyScore * 100)}%</div></div></div></div><Panel className="p-4"><h3 className="text-sm font-semibold text-ink">Detection Factors</h3><div className="mt-3 space-y-2">{alert.reasons.map((reason) => <div key={reason} className="flex items-center gap-2 rounded-md bg-panel/55 px-3 py-2 text-xs text-mute ring-1 ring-line/60"><Check className="size-3 text-cyan" />{reason}</div>)}</div><p className="mt-4 text-xs leading-relaxed text-mute">The entity was prioritized because its observed behavior differs substantially from the learned baseline. The strongest contributing signals were transaction frequency, graph connectivity, and transaction amount deviation.</p></Panel><Panel className="p-4"><h3 className="text-sm font-semibold text-ink">Evidence</h3><div className="mt-3 space-y-2">{alert.evidence.map((item) => <div key={item} className="flex items-center gap-2 rounded-md border border-line bg-panel/40 px-3 py-2 font-mono text-xs text-cyan"><ArrowDownToLine className="size-3 text-faint" />{item}</div>)}</div></Panel><Button className="w-full bg-cyan text-primary-foreground hover:bg-cyan/90" onClick={onGraph}><Network />Open in Graph</Button></div></Drawer>;
}

function GeoNetwork() {
  return <div className="space-y-5"><SectionHeader title="Geo Network" eyebrow="Country-Level Context" action={<div className="flex gap-2"><Button variant="outline" size="sm"><Filter />Country</Button><Button variant="outline" size="sm">Date range <ChevronDown /></Button></div>} /><div className="rounded-lg border border-amber/25 bg-amber/8 px-4 py-3 text-sm text-amber">Country-level metadata provides context only; a country itself is not considered suspicious.</div><div className="grid grid-cols-12 gap-4"><Panel className="col-span-12 p-5 lg:col-span-7"><div className="mb-5 flex items-center justify-between"><div><h2 className="text-sm font-semibold text-ink">Network distribution</h2><p className="mt-1 font-mono text-[11px] text-faint">IP and wallet associations by country</p></div><Globe2 className="size-5 text-cyan" /></div><div className="space-y-4">{geo.map((item, index) => <div key={item.country}><div className="mb-1.5 flex items-center justify-between text-xs"><span className="text-ink">{item.country}</span><span className="font-mono text-mute">{item.ips.toLocaleString()} IPs</span></div><div className="h-2 rounded-full bg-void"><div className={cn("h-full rounded-full", index === 0 ? "bg-cyan" : index < 3 ? "bg-blue" : "bg-safe")} style={{ width: `${Math.max(8, item.ips / 1240 * 100)}%` }} /></div></div>)}</div></Panel><Panel className="col-span-12 overflow-hidden lg:col-span-5"><div className="px-5 pb-3 pt-5"><h2 className="text-sm font-semibold text-ink">Country summary</h2></div><table className="w-full text-left font-mono text-xs"><thead className="border-y border-line bg-panel/50 text-[10px] uppercase tracking-wider text-faint"><tr><th className="px-5 py-2">Country</th><th className="px-3 py-2">Transactions</th><th className="px-3 py-2">Risk</th></tr></thead><tbody>{geo.map((item) => <tr key={item.country} className="border-b border-line/40"><td className="px-5 py-3 text-ink">{item.country}</td><td className="px-3 py-3 text-mute">{item.transactions.toLocaleString()}</td><td className="px-3 py-3"><RiskBadge risk={item.risk} /></td></tr>)}</tbody></table></Panel></div></div>;
}

function Reports() {
  const [generated, setGenerated] = useState(false);
  return <div className="space-y-6"><SectionHeader title="Reports" eyebrow="Evidence Export" action={<span className="font-mono text-[11px] text-faint">Offline report builder</span>} /><Panel className="p-6"><div className="flex flex-col gap-5 md:flex-row md:items-center md:justify-between"><div><h2 className="text-lg font-semibold text-ink">Generate Investigation Report</h2><p className="mt-1 max-w-xl text-sm text-mute">Package the dataset summary, analysis period, model output, graph relationships, top leads, explanations, and limitations for review.</p></div><Button className="bg-cyan text-primary-foreground hover:bg-cyan/90" onClick={() => setGenerated(true)}><FileBarChart />{generated ? "Report ready" : "Generate report"}</Button></div><div className="mt-6 grid gap-3 md:grid-cols-3">{[[FileText, "Export PDF", "Formatted case file"], [FileJson, "Export JSON", "Machine-readable evidence"], [Download, "Export CSV", "Filtered record set"]].map(([Icon, title, subtitle]) => <Button key={title as string} variant="outline" className="h-auto justify-start gap-3 p-4 text-left"><span className="grid size-9 place-items-center rounded-lg bg-panel text-cyan ring-1 ring-line"><Icon /></span><span><span className="block text-sm text-ink">{title as string}</span><span className="mt-1 block font-mono text-[10px] text-faint">{subtitle as string}</span></span></Button>)}</div></Panel><Panel className="p-5"><h2 className="text-sm font-semibold text-ink">Report contents</h2><div className="mt-4 grid gap-2 sm:grid-cols-2">{["Dataset summary", "Analysis period", "Alert statistics", "Top investigation leads", "Graph relationships", "AI model and feature explanations", "Limitations and synthetic-data notice", "Offline processing provenance"].map((item) => <div key={item} className="flex items-center gap-2 rounded-md bg-panel/50 px-3 py-2 font-mono text-xs text-mute ring-1 ring-line/60"><Check className="size-3 text-safe" />{item}</div>)}</div></Panel></div>;
}

function Settings() {
  return <div className="space-y-6"><SectionHeader title="Settings" eyebrow="Console Configuration" /><div className="grid gap-4 md:grid-cols-2"><Panel className="p-5"><h2 className="text-sm font-semibold text-ink">Analysis environment</h2><div className="mt-4 space-y-3">{[["Processing mode", "Offline Analysis Mode"], ["Dataset type", "Synthetic metadata"], ["ML model", "Isolation Forest"], ["Clustering", "DBSCAN candidate groups"]].map(([label, value]) => <div key={label} className="flex items-center justify-between border-b border-line/50 pb-3 font-mono text-xs"><span className="text-faint">{label}</span><span className="text-mute">{value}</span></div>)}</div></Panel><Panel className="p-5"><h2 className="text-sm font-semibold text-ink">FastAPI integration contract</h2><p className="mt-2 text-sm leading-relaxed text-mute">The mock service is isolated from the UI and can later be replaced with Python endpoints without changing screens.</p><div className="mt-4 space-y-2 font-mono text-xs text-cyan">{["POST /api/upload", "POST /api/analyze", "GET /api/dashboard", "GET /api/transactions", "GET /api/entities", "GET /api/graph", "GET /api/alerts", "GET /api/clusters", "GET /api/geo", "GET /api/reports"].map((endpoint) => <div key={endpoint} className="rounded-md bg-panel/50 px-3 py-2 ring-1 ring-line/50">{endpoint}</div>)}</div></Panel></div></div>;
}

function riskForScore(score: number): RiskLevel { return score >= 0.9 ? "Critical" : score >= 0.7 ? "High" : score >= 0.4 ? "Medium" : "Low"; }

export function BitTraceApp() {
  const [view, setView] = useState<View>("dashboard");
  const [query, setQuery] = useState("");
  const [selectedEntity, setSelectedEntity] = useState<Entity | null>(null);
  const [selectedTransaction, setSelectedTransaction] = useState<Transaction | null>(null);
  const [selectedAlert, setSelectedAlert] = useState<Alert | null>(null);
  const [analysisProgress, setAnalysisProgress] = useState<number | null>(null);
  const [analysisComplete, setAnalysisComplete] = useState(false);
  useEffect(() => {
    if (analysisProgress === null || analysisProgress >= 100) return;
    const timer = window.setTimeout(() => setAnalysisProgress((current) => current === null ? null : Math.min(100, current + 14)), 350);
    return () => window.clearTimeout(timer);
  }, [analysisProgress]);
  useEffect(() => { if (analysisProgress === 100) setAnalysisComplete(true); }, [analysisProgress]);
  const searchResults = useMemo(() => {
    if (!query.trim()) return [];
    const needle = query.toLowerCase();
    return {
      transactions: transactions.filter((tx) => tx.txid.toLowerCase().includes(needle)).slice(0, 3),
      wallets: entities.filter((entity) => entity.type === "Wallet" && entity.id.toLowerCase().includes(needle)).slice(0, 3),
      ips: entities.filter((entity) => entity.type === "IP" && entity.id.toLowerCase().includes(needle)).slice(0, 3),
    };
  }, [query]);
  const runAnalysis = () => { setAnalysisProgress(0); setView("dashboard"); };
  const goGraph = () => { setSelectedAlert(null); setSelectedEntity(null); setView("graph"); };
  const viewTitle = navItems.find((item) => item.id === view)?.label ?? "Dashboard";
  return <div className="min-h-screen bg-void text-ink" style={{ backgroundImage: "radial-gradient(1200px 500px at 75% -10%, color-mix(in oklab, var(--color-cyan) 10%, transparent), transparent 60%), radial-gradient(900px 500px at 10% 0%, color-mix(in oklab, var(--color-blue) 9%, transparent), transparent 55%)" }}>
    <div className="flex min-h-screen">
      <aside className="sticky top-0 flex h-screen w-60 shrink-0 flex-col border-r border-line/70 bg-canvas/70"><div className="flex items-center gap-2.5 border-b border-line/70 px-5 py-4"><div className="grid size-9 place-items-center rounded-xl bg-cyan/15 font-semibold text-cyan ring-1 ring-cyan/30">B</div><div className="leading-tight"><div className="text-[15px] font-semibold tracking-tight text-ink">BitTrace <span className="text-cyan">AI</span></div><div className="mt-1 font-mono text-[10px] uppercase tracking-wider text-faint">Forensic Console</div></div></div><nav className="flex-1 space-y-0.5 overflow-y-auto px-3 py-4">{navItems.map(({ id, label, icon: Icon, count }) => <button key={id} onClick={() => setView(id)} className={cn("flex w-full items-center gap-2.5 rounded-lg px-3 py-2 text-left text-sm transition-colors", view === id ? "bg-cyan/10 text-cyan ring-1 ring-cyan/25" : "text-mute hover:bg-panel/60 hover:text-ink")}><Icon className="size-4" /><span>{label}</span>{count && <span className="ml-auto rounded-md bg-crit/12 px-1.5 py-0.5 font-mono text-[10px] text-crit">{count}</span>}</button>)}</nav><div className="border-t border-line/70 p-4"><div className="mb-1.5 font-mono text-[10px] uppercase tracking-wider text-faint">System Status</div><div className="flex items-center gap-2 text-[13px] font-medium text-safe"><span className="bt-pulse size-2 rounded-full bg-safe" />Offline Analysis Mode</div><div className="mt-2 font-mono text-[11px] text-faint">Synthetic dataset · v0.4.1</div></div></aside>
      <div className="flex min-w-0 flex-1 flex-col"><header className="sticky top-0 z-30 flex min-h-14 items-center gap-4 border-b border-line/70 bg-canvas/80 px-5 backdrop-blur-xl"><div className="relative min-w-0 flex-1 max-w-md"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-faint" /><input value={query} onChange={(event) => setQuery(event.target.value)} className="h-9 w-full rounded-lg border border-line bg-panel/70 pl-9 pr-3 font-mono text-sm text-ink outline-none placeholder:text-faint focus:border-cyan/40" placeholder="Search TXID, wallet, IP, ASN…" />{query && <div className="absolute left-0 right-0 top-11 z-40 rounded-lg border border-line bg-panel-strong p-2 shadow-xl shadow-void/40"><SearchResultGroup label="Transactions" items={searchResults.transactions} onClick={(item) => { setSelectedTransaction(item); setQuery(""); }} /><SearchResultGroup label="Wallets / IPs" items={[...searchResults.wallets, ...searchResults.ips]} onClick={(item) => { setSelectedEntity(item); setQuery(""); }} /></div>}</div><div className="hidden items-center gap-2 lg:flex"><span className="rounded-md bg-panel px-2.5 py-1 font-mono text-[10px] text-mute ring-1 ring-line">Period: 12–28 Mar</span><span className="rounded-md bg-panel px-2.5 py-1 font-mono text-[10px] text-mute ring-1 ring-line">Model: Isolation Forest</span></div><Button className="bg-cyan text-primary-foreground hover:bg-cyan/90" size="sm" onClick={runAnalysis}><Play />Run Analysis</Button><Button variant="outline" size="sm" className="hidden sm:inline-flex"><Download />Export</Button></header><main className="flex-1 p-5 lg:p-6">{analysisProgress !== null && analysisProgress < 100 && <AnalysisProgress progress={analysisProgress} />}<div className="mb-6 flex items-center justify-between"><div className="font-mono text-[10px] uppercase tracking-[0.2em] text-faint">{viewTitle}</div>{analysisComplete && <span className="flex items-center gap-1.5 font-mono text-[10px] text-safe"><Check className="size-3" />Analysis Complete · 540 records processed</span>}</div>{view === "dashboard" && <Dashboard onEntity={setSelectedEntity} onView={setView} />}{view === "ingestion" && <Ingestion onRun={runAnalysis} />}{view === "transactions" && <Transactions onSelect={setSelectedTransaction} />}{view === "graph" && <Graph onEntity={setSelectedEntity} />}{view === "anomaly" && <Anomaly />}{view === "clusters" && <Clusters onGraph={() => setView("graph")} />}{view === "alerts" && <Alerts onAlert={setSelectedAlert} />}{view === "geo" && <GeoNetwork />}{view === "reports" && <Reports />}{view === "settings" && <Settings />}<footer className="mt-8 flex flex-col gap-2 border-t border-line/50 pt-4 font-mono text-[10px] text-faint sm:flex-row sm:items-center sm:justify-between"><span>Offline Analysis Mode · Synthetic Dataset · No Live Blockchain Monitoring</span><span>Raw Metadata → Correlation → AI/ML → Graph → Explainable Alert</span></footer></main></div></div>
    {selectedEntity && <EntityDrawer entity={selectedEntity} onClose={() => setSelectedEntity(null)} onGraph={goGraph} />}
    {selectedTransaction && <TransactionDrawer tx={selectedTransaction} onClose={() => setSelectedTransaction(null)} />}
    {selectedAlert && <AlertDrawer alert={selectedAlert} onClose={() => setSelectedAlert(null)} onGraph={goGraph} />}
  </div>;
}

function SearchResultGroup({ label, items, onClick }: { label: string; items: (Transaction | Entity)[]; onClick: (item: Transaction & Entity) => void }) {
  if (items.length === 0) return null;
  return <div className="mb-1 last:mb-0"><div className="px-2 py-1 font-mono text-[10px] uppercase tracking-wider text-faint">{label}</div>{items.map((item) => <button key={"txid" in item ? item.txid : item.id} onClick={() => onClick(item as Transaction & Entity)} className="flex w-full items-center justify-between rounded-md px-2 py-2 text-left text-xs text-mute hover:bg-cyan/10 hover:text-ink"><span className="font-mono">{"txid" in item ? shortId(item.txid) : shortId(item.id)}</span><span>{"txid" in item ? "Transaction" : item.type}</span></button>)}</div>;
}

function AnalysisProgress({ progress }: { progress: number }) {
  const steps = ["Dataset Loaded", "Schema Validation", "Data Cleaning", "Transaction Parsing", "IP ↔ Wallet Correlation", "Feature Engineering", "ML Anomaly Detection", "Entity Clustering", "Explainable Risk Scoring", "Investigation Alerts"];
  const active = Math.min(steps.length - 1, Math.floor(progress / 100 * steps.length));
  return <Panel className="mb-6 overflow-hidden border border-cyan/25 p-5"><div className="flex items-center justify-between"><div><div className="flex items-center gap-2"><Bot className="size-4 text-cyan" /><h2 className="text-sm font-semibold text-ink">Running AI Analysis…</h2></div><p className="mt-1 font-mono text-[11px] text-faint">Correlation pipeline is processing locally</p></div><span className="font-mono text-xl text-cyan">{progress}%</span></div><div className="mt-4 h-2 rounded-full bg-void"><div className="h-full rounded-full bg-cyan transition-all duration-300" style={{ width: `${progress}%` }} /></div><div className="mt-5 grid gap-2 sm:grid-cols-2 lg:grid-cols-5">{steps.map((step, index) => <div key={step} className={cn("flex items-center gap-2 rounded-md px-2 py-2 font-mono text-[10px]", index < active ? "bg-safe/8 text-safe" : index === active ? "bg-cyan/10 text-cyan ring-1 ring-cyan/25" : "bg-panel/50 text-faint")}>{index < active ? <Check className="size-3" /> : <span className="grid size-3 place-items-center rounded-full border border-current text-[8px]">{index + 1}</span>}{step}</div>)}</div></Panel>;
}

function EntityDrawer({ entity, onClose, onGraph }: { entity: Entity; onClose: () => void; onGraph: () => void }) {
  const connected = [{ id: "IP-192", type: "IP", connections: 12, risk: "High" as RiskLevel }, { id: "Wallet-B", type: "Wallet", connections: 8, risk: "Medium" as RiskLevel }, { id: "TX-918", type: "Transaction", connections: 1, risk: "High" as RiskLevel }];
  return <Drawer title="Entity Investigation" onClose={onClose}><div className="space-y-5"><div className="rounded-xl border border-crit/25 bg-crit/8 p-4"><div className="flex items-start justify-between"><div><div className="font-mono text-[10px] uppercase tracking-wider text-faint">{entity.type} entity</div><h3 className="mt-1 break-all font-mono text-base text-cyan">{entity.id}</h3></div><RiskBadge risk={riskForScore(entity.anomalyScore)} /></div><div className="mt-4 flex items-end gap-2"><span className="text-5xl font-semibold text-crit">{entity.riskScore}</span><span className="mb-1 font-mono text-xs text-mute">/100 risk score</span></div></div><div className="grid grid-cols-2 gap-2">{[["First seen", entity.firstSeen], ["Last seen", entity.lastSeen], ["Transactions", entity.connections * 8], ["Incoming volume", "48.21 BTC"], ["Outgoing volume", "47.93 BTC"], ["Connected IPs", 12], ["Connected wallets", entity.connections], ["Connected transactions", entity.connections * 3]].map(([label, value]) => <div key={label} className="rounded-lg bg-panel/55 p-3 ring-1 ring-line/60"><div className="font-mono text-[10px] uppercase tracking-wider text-faint">{label}</div><div className="mt-1 font-mono text-xs text-ink">{value}</div></div>)}</div><Panel className="p-4"><div className="flex items-center gap-2"><Sparkles className="size-4 text-cyan" /><h3 className="text-sm font-semibold text-ink">AI Risk Explanation</h3></div><p className="mt-3 text-xs leading-relaxed text-mute">Risk score is elevated due to {entity.reason.toLowerCase()}, {entity.connections} connected wallet entities, unusual outgoing frequency, and multiple network endpoints. Strong similarity with a suspicious entity cluster requires review.</p></Panel><Panel className="overflow-hidden"><div className="border-b border-line px-4 py-3"><h3 className="text-sm font-semibold text-ink">Connected Entities</h3></div><table className="w-full text-left font-mono text-xs"><thead className="border-b border-line/60 text-[10px] uppercase tracking-wider text-faint"><tr><th className="px-4 py-2">Entity</th><th className="px-2 py-2">Type</th><th className="px-2 py-2">Connections</th><th className="px-2 py-2">Risk</th></tr></thead><tbody>{connected.map((item) => <tr key={item.id} className="border-b border-line/40"><td className="px-4 py-3 text-cyan">{item.id}</td><td className="px-2 py-3 text-mute">{item.type}</td><td className="px-2 py-3 text-mute">{item.connections}</td><td className="px-2 py-3"><RiskBadge risk={item.risk} /></td></tr>)}</tbody></table></Panel><Button className="w-full bg-cyan text-primary-foreground hover:bg-cyan/90" onClick={onGraph}><Network />Open in Graph</Button></div></Drawer>;
}
